// ─── STORAGE & SYNC ───────────────────────────────────────────────
// ─── PROTECTION ENCODAGE UTF-8 ────────────────────────────────────
function fixEncoding(str){if(typeof str!=='string')return str;let prev=str;for(let i=0;i<10;i++){try{const fixed=decodeURIComponent(escape(prev));if(fixed===prev)break;prev=fixed;}catch(e){break;}}return prev;}
function fixAllStrings(obj){if(!obj||typeof obj!=='object')return;for(const key of Object.keys(obj)){if(typeof obj[key]==='string'){obj[key]=fixEncoding(obj[key]);}else if(Array.isArray(obj[key])){obj[key].forEach(item=>fixAllStrings(item));}else if(typeof obj[key]==='object'){fixAllStrings(obj[key]);}}}
function isCorrupted(data){try{const sample=JSON.stringify(data).slice(0,2000);return /Ã[\u0080-\u00BF]/.test(sample)||/Â[\u0080-\u00BF]/.test(sample)||/\\\\x[0-9a-f]{2}/.test(sample);}catch(e){return false;}}
