function renderContrats(){const el=document.getElementById('page-contrats');if(el)el.innerHTML='<div class="empty">Onglet desactive</div>';}
function openContratDetail(crId){const cr=D.createurs.find(x=>x.id===crId);if(!cr)return;const camp=getCamp(cr.campagne_id);const ct=getContrat(crId)||{statut:'devis_valide'};const st=getContratStatut(ct.statut);const hasAdresse=!!(ct.adresse||'').trim();const hasSiret=!!(ct.siret||'').trim();document.getElementById('modal-container').innerHTML=`<div class="modal-overlay" onclick="closeModalIfBg(event)"><div class="modal" style="max-width:720px" onclick="event.stopPropagation()"><div class="modal-title"><div><div style="font-size:16px;font-weight:600">${cr.emetteur||cr.nom||'--'}</div><div style="font-size:12px;color:var(--text2);margin-top:2px">${camp.nom||'--'} - ${camp.agence||'--'} - ${fmt(cr.montant_ht)} HT</div></div><button class="btn btn-sm" onclick="closeModal()">&#x2715;</button></div><div style="margin-bottom:20px"><div class="sl">Statut du contrat</div><div style="display:flex;gap:6px;flex-wrap:wrap">${CONTRAT_STATUTS.map(s=>{const active=ct.statut===s.id;return`<button style="font-size:12px;padding:5px 14px;border-radius:20px;border:1.5px solid ${active?s.color:'var(--border2)'};background:${active?s.bg:'var(--bg)'};color:${active?s.color:'var(--text2)'};font-weight:${active?700:500};cursor:pointer;font-family:var(--font)" onclick="setContratStatut('${crId}','${s.id}');openContratDetail('${crId}')">${s.label}</button>`;}).join('')}</div></div><div style="background:var(--info-bg);border-left:3px solid var(--info-bd);border-radius:var(--r);padding:8px 14px;margin-bottom:14px"><div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--info-bd)">1 - L'Entite</div></div><div class="form-row"><div class="field"><label>Emetteur</label><input id="ct-em" value="${(cr.emetteur||cr.nom||'').replace(/"/g,'&quot;')}"></div><div class="field"><label>Createur (pseudo)</label><input id="ct-cr" value="${(cr.createur||cr.handle||'').replace(/"/g,'&quot;')}"></div></div><div class="form-row single"><div class="field"><label>Adresse</label><input id="ct-adresse" value="${(ct.adresse||'').replace(/"/g,'&quot;')}" placeholder="15 rue des Lilas, 75001 Paris"></div></div><div class="form-row"><div class="field"><label>SIRET / SIREN</label><input id="ct-siret" value="${(ct.siret||'').replace(/"/g,'&quot;')}" placeholder="SIRET (14 chiffres)"></div><div class="field"><label>N TVA intracommunautaire</label><input id="ct-tva-intra" value="${(ct.tva_intra||'').replace(/"/g,'&quot;')}" placeholder="FR00000000000"></div></div><div style="background:var(--success-bg);border-left:3px solid var(--success-bd);border-radius:var(--r);padding:8px 14px;margin:14px 0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--success)">2 - Paiement</div></div><div class="form-row"><div class="field"><label>Montant HT (euros)</label><input id="ct-mt" type="number" value="${cr.montant_ht||''}"></div><div class="field"><label>TVA</label><select id="ct-tva"><option value="0"${!cr.tva?' selected':''}>Non assujetti (TTC = HT)</option><option value="1"${cr.tva?' selected':''}>Assujetti - 20%</option></select></div></div><div class="form-row"><div class="field"><label>IBAN</label><input id="ct-iban" value="${(cr.iban||'').replace(/"/g,'&quot;')}"></div><div class="field"><label>BIC</label><input id="ct-bic" value="${(cr.bic||'').replace(/"/g,'&quot;')}"></div></div><div class="form-row"><div class="field"><label>Reference facture</label><input id="ct-ref" value="${(cr.ref_facture||'').replace(/"/g,'&quot;')}"></div><div class="field"><label>Date facture recue</label><input id="ct-dfact" type="date" value="${cr.date_facture||''}"></div></div><div class="form-row single"><div class="field"><label>Date paiement souhaitee</label><input id="ct-dpay" type="date" value="${cr.date_paiement_souhaite||''}"></div></div><div style="background:var(--warning-bg);border-left:3px solid var(--warning-bd);border-radius:var(--r);padding:8px 14px;margin:14px 0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--warning)">3 - Le Projet</div></div><div class="form-row"><div class="field"><label>Client (agence)</label><input id="ct-client" value="${(ct.client||camp.agence||'').replace(/"/g,'&quot;')}"></div><div class="field"><label>Marque</label><input id="ct-marque" value="${(ct.marque||'').replace(/"/g,'&quot;')}"></div></div><div class="form-row"><div class="field"><label>Nb contenus</label><input id="ct-nb" type="number" value="${cr.nb_contenus||1}"></div><div class="field"><label>Type de contenus</label><input id="ct-type" value="${(cr.type_contenus||'').replace(/"/g,'&quot;')}"></div></div><div class="form-row single"><div class="field"><label>Plateformes autorisees</label><input id="ct-plat" value="${(ct.plateformes||'').replace(/"/g,'&quot;')}" placeholder="Instagram, TikTok, Facebook"></div></div><div class="form-row"><div class="field"><label>Periode d'exploitation</label><input id="ct-periode" value="${(ct.periode||'').replace(/"/g,'&quot;')}" placeholder="Juin + Juillet 2026"></div><div class="field"><label>Budget media max (euros)</label><input id="ct-budmed" type="number" value="${ct.budget_media||''}"></div></div><div class="form-row single"><div class="field"><label>Date du contrat</label><input id="ct-dcontrat" type="date" value="${ct.date_contrat||''}"></div></div><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:20px;flex-wrap:wrap"><button class="btn" onclick="closeModal()">Fermer</button><button class="btn btn-primary" onclick="saveContratDetailFull('${crId}')">Enregistrer</button><button id="btn-generer" class="btn btn-success" onclick="genererContrat('${crId}')" style="${hasAdresse&&hasSiret?'':'opacity:.4;cursor:not-allowed;pointer-events:none'}">Generer .docx</button></div></div></div>`;setTimeout(()=>{const upd=()=>{const b=document.getElementById('btn-generer');if(!b)return;const ok=!!(document.getElementById('ct-adresse')?.value.trim())&&!!(document.getElementById('ct-siret')?.value.trim());b.style.opacity=ok?'1':'0.4';b.style.pointerEvents=ok?'auto':'none';b.style.cursor=ok?'pointer':'not-allowed';};document.getElementById('ct-adresse')?.addEventListener('input',upd);document.getElementById('ct-siret')?.addEventListener('input',upd);upd();},50);}
function saveContratDetailFull(crId){const cr=D.createurs.find(x=>x.id===crId);if(!cr)return;cr.emetteur=document.getElementById('ct-em').value.trim();cr.nom=cr.emetteur;cr.createur=document.getElementById('ct-cr').value.trim();cr.handle=cr.createur;cr.montant_ht=parseFloat(document.getElementById('ct-mt').value)||cr.montant_ht;cr.tva=document.getElementById('ct-tva').value==='1';cr.iban=document.getElementById('ct-iban').value.trim();cr.bic=document.getElementById('ct-bic').value.trim();cr.ref_facture=document.getElementById('ct-ref').value.trim();cr.date_facture=document.getElementById('ct-dfact').value;cr.date_paiement_souhaite=document.getElementById('ct-dpay').value;cr.nb_contenus=parseInt(document.getElementById('ct-nb').value)||1;cr.type_contenus=document.getElementById('ct-type').value.trim();setContrat(crId,{adresse:document.getElementById('ct-adresse').value.trim(),siret:document.getElementById('ct-siret').value.trim(),tva_intra:document.getElementById('ct-tva-intra').value.trim(),client:document.getElementById('ct-client').value.trim(),marque:document.getElementById('ct-marque').value.trim(),plateformes:document.getElementById('ct-plat').value.trim(),periode:document.getElementById('ct-periode').value.trim(),budget_media:parseFloat(document.getElementById('ct-budmed').value)||0,date_contrat:document.getElementById('ct-dcontrat').value});save();openContratDetail(crId);}
function setContratStatut(crId,statut){setContrat(crId,{statut});if(curCampId)openContratDetail(crId);}
function toggleCampContrat(cid){if(!window._openCamps)window._openCamps={};window._openCamps[cid]=!window._openCamps[cid];renderContrats();}

async function genererContrat(crId){const cr=D.createurs.find(x=>x.id===crId);if(!cr)return;const camp=getCamp(cr.campagne_id);const ct=getContrat(crId)||{};if(!ct.adresse||!ct.siret){alert('Veuillez renseigner l\'adresse et le SIRET avant de generer le contrat.');return;}const emetteur=cr.emetteur||cr.nom||'';const marque=ct.marque||camp.agence||'';const platefList=(ct.plateformes||'').split(',').map(p=>p.trim()).filter(Boolean);const platefStr=platefList.length?platefList.join(', '):'[Plateformes]';const replacements={'{{EMETTEUR}}':emetteur,'{{ADRESSE}}':ct.adresse||'','{{SIRET}}':ct.siret||'','{{TVA_INTRA}}':cr.tva?(ct.tva_intra||'[N TVA intra]'):'Non assujetti(e) a la TVA','{{MARQUE}}':marque,'{{NB_CONTENUS}}':String(cr.nb_contenus||1),'{{TYPE_CONTENUS}}':cr.type_contenus||'contenus','{{PLATEFORMES}}':platefStr,'{{PERIODE}}':ct.periode||'[Periode]','{{BUDGET_MEDIA}}':ct.budget_media?(new Intl.NumberFormat('fr-FR').format(ct.budget_media)+' euros'):'[Budget media]','{{MONTANT_HT}}':new Intl.NumberFormat('fr-FR').format(cr.montant_ht||0),'{{DATE_CONTRAT}}':ct.date_contrat?fmtD(ct.date_contrat):'[Date]'};try{const binary=atob(CONTRAT_TEMPLATE_B64);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const zip=await JSZip.loadAsync(bytes);let docXml=await zip.file('word/document.xml').async('string');for(const[key,val]of Object.entries(replacements)){docXml=docXml.split(key).join(val.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'));}zip.file('word/document.xml',docXml);const blob=await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Contrat_'+emetteur.replace(/[^a-zA-Z0-9]/g,'_')+'_x_'+marque.replace(/[^a-zA-Z0-9]/g,'_')+'.docx';a.click();URL.revokeObjectURL(url);if(ct.statut==='contrat_editer'){setContrat(crId,{statut:'contrat_envoye'});openContratDetail(crId);}}catch(e){console.error('Erreur generation docx:',e);alert('Erreur lors de la generation : '+e.message);}}

async function importerFacturePDF(input,cid){const file=input.files[0];if(!file)return;const statusEl=document.getElementById('pdf-import-status');statusEl.style.display='block';statusEl.style.background='var(--info-bg)';statusEl.style.color='var(--info-bd)';statusEl.innerHTML='Lecture du PDF en cours...';try{const base64=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=()=>rej(new Error('Lecture impossible'));r.readAsDataURL(file);});statusEl.innerHTML='Extraction des donnees par IA...';let pdfText='';const msgContent=[{type:'document',source:{type:'base64',media_type:'application/pdf',data:base64}},{type:'text',text:'Extrais les informations de cette facture. Reponds UNIQUEMENT en JSON valide sans markdown. Format: {"emetteur":"nom legal","pseudo":"nom commercial ou vide","adresse":"adresse complete","siret":"numero SIRET (14 chiffres) ou SIREN (9 chiffres) sans espaces","tva_intra":"numero TVA intra ou vide","tva_assujetti":false,"iban":"IBAN sans espaces","bic":"BIC","montant_ht":0,"montant_ttc":0,"ref_facture":"","date_facture":"YYYY-MM-DD","type_contenus":"description courte","nb_contenus":1}'}];let resp,lastErr;for(let attempt=1;attempt<=3;attempt++){try{resp=await fetch('https://oneco-proxy.julslambert.workers.dev',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-opus-4-5',max_tokens:1000,messages:[{role:'user',content:msgContent}]})});if(resp.ok)break;lastErr='API '+resp.status;if(resp.status===500&&attempt<3){statusEl.innerHTML='Tentative '+attempt+'/3 - nouvelle tentative...';await new Promise(r=>setTimeout(r,2000*attempt));}else if(!resp.ok){throw new Error(lastErr);}}catch(e){lastErr=e.message;if(attempt<3){statusEl.innerHTML='Tentative '+attempt+'/3 - nouvelle tentative...';await new Promise(r=>setTimeout(r,2000*attempt));}else{throw new Error(lastErr);}}}if(!resp||!resp.ok)throw new Error(lastErr||'Erreur API');const data=await resp.json();const raw=data.content.filter(b=>b.type==='text').map(b=>b.text).join('');let info;try{info=JSON.parse(raw.replace(/```json|```/g,'').trim());}catch(e){throw new Error('Reponse non parseable');}const fill=(id,v)=>{const el=document.getElementById(id);if(el&&v!==undefined&&v!==null&&String(v)!=='')el.value=v;};const emLower=(info.emetteur||'').toLowerCase();const crsDeCetteCamp=D.createurs.filter(cr=>cr.campagne_id===cid);const crsTousEmetteur=D.createurs.filter(cr=>(cr.emetteur||cr.nom||'').toLowerCase()===emLower);const doublonExact=crsDeCetteCamp.find(cr=>(cr.emetteur||cr.nom||'').toLowerCase()===emLower&&cr.ref_facture&&info.ref_facture&&cr.ref_facture===info.ref_facture);if(doublonExact){let nbMaj=0;crsTousEmetteur.forEach(cr=>{if(!cr.iban&&info.iban){cr.iban=info.iban;nbMaj++;}if(!cr.bic&&info.bic){cr.bic=info.bic;nbMaj++;}const ct=getContrat(cr.id)||{};const ctUpdate={};if(!ct.adresse&&info.adresse){ctUpdate.adresse=info.adresse;nbMaj++;}if(!ct.siret&&info.siret){ctUpdate.siret=info.siret;nbMaj++;}if(!ct.tva_intra&&info.tva_intra){ctUpdate.tva_intra=info.tva_intra;nbMaj++;}if(Object.keys(ctUpdate).length>0)setContrat(cr.id,ctUpdate);});if(nbMaj>0){save();}statusEl.style.background=nbMaj>0?'var(--success-bg)':'var(--info-bg)';statusEl.style.color=nbMaj>0?'var(--success)':'var(--info-bd)';statusEl.innerHTML=nbMaj>0?'Facture deja saisie - '+nbMaj+' info'+(nbMaj>1?'s':'')+' completee'+(nbMaj>1?'s':'')+'.':'Facture deja saisie et informations deja completes.';return;}const known=getCreateurInfosExistantes(info.emetteur);const refCr=crsDeCetteCamp.find(cr=>(cr.emetteur||cr.nom||'').toLowerCase()===emLower)||crsTousEmetteur[0]||null;fill('cr-em',info.emetteur);fill('cr-cr',info.pseudo||(refCr?refCr.createur||refCr.handle:''));fill('cr-adresse',info.adresse||known.adresse);fill('cr-siret',info.siret||known.siret);fill('cr-tva-intra',info.tva_intra||known.tva_intra);fill('cr-iban',info.iban||known.iban);fill('cr-bic',info.bic||known.bic);fill('cr-mt',info.montant_ht);fill('cr-ref',info.ref_facture);fill('cr-dfact',info.date_facture);fill('cr-type',info.type_contenus);fill('cr-nb',info.nb_contenus||1);const tvaSel=document.getElementById('cr-tva');if(tvaSel)tvaSel.value=info.tva_assujetti?'1':'0';if(info.date_facture){const d=new Date(info.date_facture);d.setDate(d.getDate()+45);fill('cr-dpay',d.toISOString().split('T')[0]);}statusEl.style.background='var(--success-bg)';statusEl.style.color='var(--success)';statusEl.innerHTML=refCr?'Createur connu - infos pre-remplies. Completez marque, plateformes...':'Nouveau createur - champs pre-remplis depuis la facture. Completez marque, plateformes...';}catch(e){statusEl.style.background='var(--danger-bg)';statusEl.style.color='var(--danger)';statusEl.innerHTML='Erreur : '+e.message;}}

